const express = require('express');
const Pool = require('pg-pool');
const { WorkspaceMembership } = require('../models/workspace');

const app = express();
app.use(express.json());

const poolRegistry = new Map();

function getPool(workspaceSlug) {
  if (!poolRegistry.has(workspaceSlug)) {
    poolRegistry.set(
      workspaceSlug,
      new Pool({
        host: 'postgres-cluster.internal',
        database: `ws_${workspaceSlug}`,
        user: 'service_role',
        password: process.env.DB_PASSWORD
      })
    );
  }
  return poolRegistry.get(workspaceSlug);
}

app.post('/api/workspaces/:workspaceSlug/query', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { workspaceSlug } = req.params;
  const { filterField, filterValue } = req.body;

  // Verify caller membership in the target workspace
  const isMember = await WorkspaceMembership.checkMembership(req.user.id, workspaceSlug);
  if (!isMember) {
    return res.status(403).json({ error: 'Access denied: not a member of this workspace' });
  }

  const pool = getPool(workspaceSlug);

  try {
    const { rows } = await pool.query(
      'SELECT id, name, client_secrets, created_at FROM client_projects WHERE status = $1',
      [filterValue]
    );
    res.json({ workspace: workspaceSlug, projects: rows });
  } catch (err) {
    res.status(500).json({ error: 'Workspace database query error' });
  }
});

app.listen(9102);
